Input: {"decision_time_ms": 1789937999999, "macro_contexts": {"D1": {"context": {"always_in": "long", "always_in_relevance": "low", "breakout_mode": true, "confidence": "medium", "decision_time_ms": 1789862399999, "directional_pressure": "bull", "evidence_against": ["Bar 90's 2771 high with a close 255.7 lower is a buy-climax bar, and the 29 bars since then overlap inside the range rather than trending - trading-range behavior after a climax.", "No close has exceeded 2771; the recent highs 2680 (bar 111) and 2700 (bar 119) are below the spike high, so the range top has already rejected the bulls.", "Bar 115 fell from 2517.53 to 2358.62 in a single bar, showing fast two-sided movement inside the range and poor trend persistence.", "The final bar closed 67.02 below its own 2700 high, so there is no acceptance yet at the upper boundary; the bull push is an in-range leg, not a confirmed breakout.", "The 2357.18 and 2358.62 lows are roughly equal, which marks a range floor that has been tested twice and can break rather than hold."], "evidence_for": ["Net window change is upward (open 2066.43 to close 2632.98) and the post-crash lows rose: 1368.42 (bar 14), 1512.91 (bar 34), 1803.74 (bar 55), 1821.49 (bar 72), 2357.18 (bar 102).", "Bar 88 broke out of a roughly 27-bar consolidation with a 377.29-point range (1905.63-2293.8) closing at 2252.16, and bars 89-90 followed through to 2771, satisfying the breakout-plus-follow-through test.", "Price holds well above the breakout: the last close 2632.98 is about 38% above bar 88's 1905.63 low and has not returned to bar 89's 2111 low.", "The most recent leg is bull: four consecutive higher closes off the 2358.62 double-bottom retest, and bar 119's 2632.98 is the highest close in the supplied window.", "The post-spike range has held above the spike bar's 2325.31 low and keeps making higher swing lows inside the range (2357.18 then 2358.62 with a higher close)."], "missing_information": [], "observations": ["120 closed D1 bars, open_time 1779494400000 to 1789776000000, with the decision at the close of the final bar (close_time 1789862399999).", "Window high is 2771 (bar 90, open_time 1787270400000); window low is 1368.42 (bar 14, open_time 1780704000000).", "Bars 10-14 (1780358400000-1780704000000) are five overlapping bear bars driving 2006.17 down to 1368.42; bar 14 closes 1568.55, about 200 points above its low, a sell-climax tail.", "Bar 88 (1787097600000) opens 1916.51 inside the prior consolidation and closes 2252.16 near its 2293.8 high; bars 89-90 close 2326.32 and 2515.3, and bar 90 prints 2771 and closes 255.7 below that high.", "Bars 91-119 overlap between 2357.18 (bar 102 low, 1788307200000) and 2700 (bar 119 high); bar 90's low of 2325.31 was never revisited.", "Roughly equal lows at 2357.18 (bar 102) and 2358.62 (bar 115, 1789430400000) form a double bottom at the range low, followed by four higher closes (2416.57, 2446.22, 2612.02, 2632.98).", "The final bar's close 2632.98 is the highest close in the whole window, while its high 2700 stays 71 below bar 90's 2771 high; the last bar closes 67.02 under its own high."], "phase": "range", "primary_regime": "bull-trend", "role": "CONTEXT_ANALYST", "schema": "brooks.market-context.v2", "structures": [{"description": "Bear leg into a sell climax: bars 0-14 decline from bar 0's 2143.61 high to bar 14's 1368.42 low; the final bars are large bear trend bars and bar 14 closes 200.13 above its low.", "end_time_ms": 1780790399999, "kind": "climax", "lower_boundary": "1368.42", "start_time_ms": 1779494400000, "upper_boundary": "2143.61"}, {"description": "Two-sided consolidation (bars 61-87, about 27 bars): upper boundary is bar 65's 1974.46 high with repeated 1919-1938 highs; lower boundary is the triple equal low 1821.69/1821.59/1821.49 (bars 70-72). Bar 88 later opened at 1916.51 inside it before breaking out.", "end_time_ms": 1787183999999, "kind": "range", "lower_boundary": "1821.49", "start_time_ms": 1784764800000, "upper_boundary": "1974.46"}, {"description": "Three-bar bull spike (bars 88-90): 1916.51 to 2252.16 to 2326.32 to a 2515.3 close, with bar 90 reaching 2771 and closing 255.7 off the high - a buy-climax bar.", "end_time_ms": 1787356799999, "kind": "breakout", "lower_boundary": "1905.63", "start_time_ms": 1787097600000, "upper_boundary": "2771"}, {"description": "Post-climax trading range (bars 91-119): upper boundary 2771.00 with internal highs capped at 2557.46, 2537.57, 2680 and 2700; lower boundary 2357.18 (bar 102 low), retested at 2358.62 (bar 115).", "end_time_ms": 1789862399999, "kind": "range", "lower_boundary": "2357.18", "start_time_ms": 1787356800000, "upper_boundary": "2771"}, {"description": "Recent bull leg: four consecutive bull closes from bar 115's 2358.62 low to bar 119's 2700 high; bar 119's close 2632.98 is the highest close of the window.", "end_time_ms": 1789862399999, "kind": "swing", "lower_boundary": "2358.62", "start_time_ms": 1789430400000, "upper_boundary": "2700"}], "symbol": "ETH-USDT", "timeframe": "D1", "transition_conditions": ["A close above 2771 followed by a bar holding above 2771 would confirm a bull breakout and move the read toward breakout-spike/channel.", "Rejection at 2700-2771 with a bear close back below 2604.75 keeps the range classification and supports rotation back toward the 2400 area.", "A close below 2357.18 would break the range's double bottom and shift the read toward a range breakdown or deeper bear leg.", "A close below 2111 (bar 89 low) or 1905.63 (bar 88 low) would negate the bull breakout structure and make the bear side the structural read.", "Continued overlapping bars closing between roughly 2400 and 2700 would keep phase as range and Always-In relevance low."], "window_bars": 120}, "freshness": "current"}, "H4": {"context": {"always_in": "long", "always_in_relevance": "medium", "breakout_mode": true, "confidence": "medium", "decision_time_ms": 1789934399999, "directional_pressure": "bull", "evidence_against": ["The recent leg is strongly directional: bars 96-112 rose 329.46 points with 12 of 16 closes higher, which is closer to a bull trend leg than to range rotation.", "The breakout cleared every prior window high (2680.00 and 2609.02), so it is not merely an internal range probe.", "The pullback low 2568.16 held above bar 84's 2544.63 high and above the bars 96-106 rise, and bars 119-120 closed at/near their highs, which also fits a bull flag inside a new leg rather than range continuation.", "Window highs are rising (2537.57 bar 22, 2680.00 bar 65, 2700.00 bar 112) and lows since bar 90 are rising, an ascending structure that weakens the balanced-range reading."], "evidence_for": ["The window combines repeated strong legs in both directions (bull: bar 17, bars 107-108; bear: bar 23, bar 89) with long stretches of small overlapping bars (bars 24-31, 67-75, 92-100), the defining quality of a two-sided range.", "Prior probes above 2600 were rejected: bar 65 spiked to 2680.00 and closed 2555.52; bar 85 spiked to 2609.02 and closed 2514.07.", "After the new high 2700.00 (bar 112) price gave back 131.84 points in six bars to 2568.16, trading back below the 2609.02 breakout level, so breakout acceptance above the range top is not established.", "The final close 2631.93 sits at the range's upper boundary (about 80% of the 2357.18-2700.00 band) and near the bars 107-108 breakout closes of 2578.60 and 2636.28, i.e. still at the top of the range rather than clear of it.", "The lower boundary has been retested flat: 2357.18 (bar 10), 2358.62 (bar 90), 2370.54 (bar 96)."], "missing_information": [], "observations": ["120 closed H4 bars span open_time_ms 1788206400000 to close_time_ms 1789934399999; the window's absolute range is 2357.18 (bar 10 low) to 2700.00 (bar 112 high); final close 2631.93, about 80% of that range.", "Bar 17 (open 2407.48, close 2506.79) is the first large bull trend bar, breaking out of the bars 10-16 base whose lows are 2357.18-2417.19.", "Bar 23 (high 2527.18, close 2450.96, low 2436.73) reversed the bars 17-22 leg (high 2537.57) with a bear body closing near its low.", "Bars 24-53 are mostly small, heavily overlapping bars between 2441.33 and 2528.80 (bar 38 high) with no sustained follow-through in either direction.", "Bar 65 spiked to 2680.00 and closed 2555.52 (upper tail 124.48); bar 85 spiked to 2609.02 and closed 2514.07: two rejected probes above 2600.", "Bars 85-96 fell to 2358.62 (bar 90 low) then 2370.54 (bar 96 low), a marginally higher low versus bar 90.", "Bars 96-112 rose from 2370.54 to 2700.00; 12 of the 16 bar-to-bar closes in that stretch were higher.", "Bars 107-108 are the biggest bull bodies of the advance (opens 2507.15 and 2579.97, closes 2578.60 and 2636.28) and traded above the bar 85 high of 2609.02.", "Bar 112 printed the window high 2700.00 but closed 2638.49, leaving a 61.51 upper tail.", "Bars 113-118 pulled back to 2568.16 (bar 118 low), about 40% of the 2370.54-2700.00 leg but about 65% of the 2495.82-2700.00 spike; the low held above the bar 84 high of 2544.63.", "Bars 119-120 are bull bars closing at/near their highs (bar 119 close 2611.00 equals its high; bar 120 close 2631.93 is 65% of its 2605.96-2645.88 range).", "Final close 2631.93 is back above the 2609.02 breakout level but below bar 114's 2658.79 high and below the 2700.00 window high."], "phase": "breakout-spike", "primary_regime": "trading-range", "role": "CONTEXT_ANALYST", "schema": "brooks.market-context.v2", "structures": [{"description": "Large two-sided trading range covering most of the window: repeated bull legs (bars 17-22, 32-38) and bear legs (bars 6-10, 23, 54-65, 85-96) between 2357.18 and 2700.00 with heavy overlap and no sustained follow-through; most trade occurred below 2650.00.", "end_time_ms": 1789934399999, "kind": "range", "lower_boundary": "2357.18", "start_time_ms": 1788206400000, "upper_boundary": "2700"}, {"description": "Bull breakout attempt: bars 107-108 spiked above the bar 85 high of 2609.02 and bars 109-112 extended to a new window high 2700.00. The move is now being tested by the bars 113-118 pullback, which traded back below 2609.02 before bars 119-120 recovered it.", "end_time_ms": 1789804800000, "kind": "breakout", "lower_boundary": "2495.82", "start_time_ms": 1789732800000, "upper_boundary": "2700"}, {"description": "Bull swing from the bar 96 low 2370.54 to the bar 112 high 2700.00 (higher low versus bar 90's 2358.62), built from a series of higher closes with the bars 107-108 spike in its middle.", "end_time_ms": 1789804800000, "kind": "swing", "lower_boundary": "2370.54", "start_time_ms": 1789574400000, "upper_boundary": "2700"}, {"description": "Post-spike consolidation / bull-flag band: bars 112-120 have held between 2568.16 and 2658.79 after the 2700.00 high, with the last two bars lifting back toward the upper part of the band.", "end_time_ms": 1789920000000, "kind": "range", "lower_boundary": "2568.16", "start_time_ms": 1789804800000, "upper_boundary": "2658.79"}, {"description": "Unconfirmed higher-high reversal candidate: bar 112 made a marginal new high 2700.00 after the bars 107-108 buy spike and the next six bars closed lower. Not confirmed, because bars 119-120 recovered 63.77 from the 2568.16 low and closed near their highs.", "end_time_ms": 1789920000000, "kind": "mtr-like", "lower_boundary": "2568.16", "start_time_ms": 1789804800000, "upper_boundary": "2700"}], "symbol": "ETH-USDT", "timeframe": "H4", "transition_conditions": ["Bull acceptance: a close above 2658.79 (bar 114 high) that holds on the next pullback, followed by a close above 2700.00 with the bar closing in its upper third, would argue the breakout is being accepted and shift the read toward bull-trend.", "Failed breakout: a close below 2568.16 (bar 118 low) would put price back under the bars 107-112 spike and back inside the bars 96-106 area, opening 2544.63 and then 2495.82 (bar 107 low).", "Spike negation: a close below 2495.82 would negate the bars 107-112 spike and re-open the 2358-2410 lower boundary.", "Continued overlap: alternating bull and bear bars with closes in the middle of the 2568.16-2700.00 band would keep the primary read as trading-range.", "A second consecutive close below 2609.02 would confirm the 2700.00 high as another failed probe and favor a return toward the mid-2500s."], "window_bars": 120}, "freshness": "current"}}, "raw": {"H1": [{"close": "2390.44", "close_time_ms": 1789509599999, "high": "2407.01", "low": "2390.01", "open": "2407.01", "open_time_ms": 1789506000000, "volume": "2166076.656"}, {"close": "2395.63", "close_time_ms": 1789513199999, "high": "2400.08", "low": "2381", "open": "2390.44", "open_time_ms": 1789509600000, "volume": "2292207.597"}, {"close": "2397.1", "close_time_ms": 1789516799999, "high": "2411.04", "low": "2395.62", "open": "2395.63", "open_time_ms": 1789513200000, "volume": "1968246.019"}, {"close": "2398.86", "close_time_ms": 1789520399999, "high": "2404.38", "low": "2396.92", "open": "2397.12", "open_time_ms": 1789516800000, "volume": "1974436.218"}, {"close": "2390.24", "close_time_ms": 1789523999999, "high": "2404.93", "low": "2389.75", "open": "2398.78", "open_time_ms": 1789520400000, "volume": "2312531.024"}, {"close": "2401.9", "close_time_ms": 1789527599999, "high": "2408.08", "low": "2388.06", "open": "2390.24", "open_time_ms": 1789524000000, "volume": "2418665.183"}, {"close": "2400.78", "close_time_ms": 1789531199999, "high": "2409.46", "low": "2399.39", "open": "2401.92", "open_time_ms": 1789527600000, "volume": "1776686.57"}, {"close": "2402.56", "close_time_ms": 1789534799999, "high": "2408.41", "low": "2399.39", "open": "2401.43", "open_time_ms": 1789531200000, "volume": "1968226.465"}, {"close": "2405.82", "close_time_ms": 1789538399999, "high": "2405.84", "low": "2395.06", "open": "2402.55", "open_time_ms": 1789534800000, "volume": "1752934.626"}, {"close": "2404.65", "close_time_ms": 1789541999999, "high": "2407.28", "low": "2393.36", "open": "2405.84", "open_time_ms": 